begin read only;
set local statement_timeout='20s';
select jsonb_build_object('observed_at',clock_timestamp(),'tables',(select jsonb_agg(to_jsonb(x))from(select n.nspname schema,c.relname name,c.relrowsecurity rls,(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull)order by a.attnum)from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)columns,has_table_privilege('anon',c.oid,'select')anon_select,has_table_privilege('authenticated',c.oid,'select')authenticated_select from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and(n.nspname in('public','spot_private')or(n.nspname='auth'and c.relname in('users','identities','sessions','refresh_tokens','audit_log_entries','mfa_factors'))or(n.nspname='storage'and c.relname in('objects','buckets'))))x),'foreign_keys',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',r.relname,'name',c.conname,'definition',pg_get_constraintdef(c.oid)))from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace n on n.oid=r.relnamespace where c.contype='f'and n.nspname in('public','spot_private')),'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check))from pg_policies where schemaname in('public','spot_private','storage')));
rollback;
